const DEFAULT_THEME={site_title:"Үздіксіз білім беру платформасы",font_family:"Inter",heading_font:"Inter",base_size:16,heading_scale:100,background:"#f5f8fc",surface:"#ffffff",text:"#172e49",muted:"#55677e",school:"#1378cf",university:"#1866ae",bridge:"#0b7e83",diagnostic:"#2869a6",card_radius:30,button_radius:14,content_width:1240,page_gutter:30,density:"comfortable",header_style:"floating",hero_style:"spotlight",card_style:"glass",home_layout:"bento",background_style:"aurora",shadow_style:"soft",visual_effects:true};
