function normalizeItems(items=[]){return items.map((item)=>{let item_type=item.item_type||"lesson";if(!item.item_type){if(["school-root","university-root","bridge-root","school-theory"].includes(item.id))item_type="program";else if(item.id?.startsWith("grade-")||["school-program","school-profile","school-ubt","university-syllabus","university-theory","university-self","diagnostic-root"].includes(item.id))item_type="course";else if(["school-map","university-map"].includes(item.id))item_type="report";}const content_mode=item.content_mode||(["school-program","university-syllabus"].includes(item.id)?"resources":"curriculum");return{...item,item_type,content_mode};});}
function slugify(value=""){const map={а:"a",ә:"a",б:"b",в:"v",г:"g",ғ:"g",д:"d",е:"e",ё:"e",ж:"zh",з:"z",и:"i",й:"i",к:"k",қ:"q",л:"l",м:"m",н:"n",ң:"n",о:"o",ө:"o",п:"p",р:"r",с:"s",т:"t",у:"u",ұ:"u",ү:"u",ф:"f",х:"h",һ:"h",ц:"c",ч:"ch",ш:"sh",щ:"sh",ы:"y",і:"i",э:"e",ю:"yu",я:"ya",ь:"",ъ:""};return String(value).toLowerCase().split("").map((char)=>map[char]??char).join("").normalize("NFKD").replace(/[^a-z0-9]+/g,"-").replace(/^-|-$/g,"")||"sabak";}
function applyTheme(){const root=document.documentElement,s={...DEFAULT_THEME,...state.settings},fonts={Inter:"Inter,system-ui,sans-serif",Manrope:"Manrope,Inter,system-ui,sans-serif",Arial:"Arial,sans-serif",Georgia:"Georgia,serif","Courier New":"Courier New,monospace"};root.style.setProperty("--paper",s.background);root.style.setProperty("--sheet",s.surface);root.style.setProperty("--ink",s.text);root.style.setProperty("--muted",s.muted);root.style.setProperty("--school",s.school);root.style.setProperty("--uni",s.university);root.style.setProperty("--bridge",s.bridge);root.style.setProperty("--diagnostic",s.diagnostic);root.style.setProperty("--site-font",fonts[s.font_family]||fonts.Inter);root.style.setProperty("--heading-font",fonts[s.heading_font]||fonts.Inter);root.style.setProperty("--base-size",`${s.base_size}px`);root.style.setProperty("--heading-scale",String(s.heading_scale/100));root.style.setProperty("--card-radius",`${s.card_radius}px`);root.style.setProperty("--button-radius",`${s.button_radius}px`);root.style.setProperty("--site-width",`${s.content_width}px`);root.style.setProperty("--page-gutter",`${s.page_gutter}px`);root.style.setProperty("--ui-shadow",s.shadow_style==="none"?"none":s.shadow_style==="strong"?"0 24px 70px rgba(0,0,0,.34)":"0 16px 46px rgba(0,0,0,.2)");Object.assign(document.body.dataset,{density:s.density,header:s.header_style,hero:s.hero_style,cards:s.card_style,home:s.home_layout,background:s.background_style});document.body.classList.toggle("effects-off",!s.visual_effects);}
const quizQuestions=(quiz={})=>Array.isArray(quiz.questions)?quiz.questions.filter((entry)=>entry?.question):quiz.question?[quiz]:[];
function sanitizeRichText(value=""){
  const doc=new DOMParser().parseFromString(`<div>${value}</div>`,"text/html");
  const allowed=new Set(["DIV","P","BR","STRONG","B","EM","I","U","H2","H3","H4","UL","OL","LI","BLOCKQUOTE","SPAN","FONT","A"]);
  const styles=new Set(["font-family","font-size","text-align","color"]);
  [...doc.body.querySelectorAll("*")].forEach((node)=>{
    if(!allowed.has(node.tagName)){node.replaceWith(...node.childNodes);return;}
    [...node.attributes].forEach((attribute)=>{
      const name=attribute.name.toLowerCase();
      if(name==="style"){
        const safe=[...node.style].filter((key)=>styles.has(key)).map((key)=>`${key}:${node.style.getPropertyValue(key)}`).join(";");
        safe?node.setAttribute("style",safe):node.removeAttribute("style");
      }else if(node.tagName==="A"&&name==="href"){
        if(!/^(https?:|\/)/i.test(attribute.value))node.removeAttribute(name);
      }else if(!(node.tagName==="FONT"&&["face","size","color"].includes(name)))node.removeAttribute(name);
    });
    if(node.tagName==="A"&&node.hasAttribute("href")){node.setAttribute("target","_blank");node.setAttribute("rel","noopener");}
  });
  return doc.body.firstElementChild?.innerHTML||"";
}

function navigate(path,replace=false){state.menuOpen=false;if(path==="/admin")state.adminTab="dashboard";const target=browserPath(path);if(replace)history.replaceState({},"",target);else history.pushState({},"",target);window.scrollTo({top:0,behavior:"smooth"});render();app.querySelector("h1")?.focus({preventScroll:true});hydrateRoute();}
function showToast(message,tone="success"){
  document.querySelector('.toast')?.remove();const node=document.createElement('div');node.className=`toast ${tone}`;node.setAttribute('role',tone==='error'?'alert':'status');node.textContent=errorMessage(message);document.body.append(node);setTimeout(()=>node.remove(),5000);
}

function header(active=""){
 const account=state.user?`<a href="/kabinet">Менің профилім</a>${state.user.role==='admin'?'<a href="/admin">Басқару панелі</a>':''}<button class="text-button" data-action="logout">Шығу</button>`:'<a class="nav-pill" href="/login">Кіру / Тіркелу</a>';
 return `<header class="topbar"><a class="brand" href="/" aria-label="ChemBridge — басты бет"><strong>ChemBridge<span>Мектеп–ЖОО сабақтастығы</span></strong></a><button class="menu-toggle" aria-label="Мәзір" aria-expanded="${state.menuOpen}" aria-controls="main-nav">☰</button><nav id="main-nav" class="${state.menuOpen?'open':''}" aria-label="Негізгі навигация"><a href="/" ${active==='home'?'aria-current="page"':''}>Басты бет</a><a href="/materials" ${active==='materials'?'aria-current="page"':''}>Материалдар</a><a href="/topics">Тақырыптар</a><a href="/sabaktastyk-kopiri">Сабақтастық</a>${account}</nav></header>`;
}
function shell(content,active=""){return `<main class="site-shell" id="main"><div class="paper-grid" aria-hidden="true"></div>${header(active)}${content}<footer class="learning-footer"><span>ChemBridge · Үздіксіз білім беру</span><a href="/sabaktastyk-kopiri">Сабақтастық көпірі →</a></footer>${state.toast?`<div class="toast ${state.toast.tone}" role="status">${escapeHtml(state.toast.message)}</div>`:""}${state.deleting?deleteDialog():""}${state.previewing?filePreviewDialog(state.previewing):""}</main>`;}

