function orderedTopicItems(items){
  const gradeOf=(item)=>item.path.startsWith("/mektep/")?Number(item.path.match(/\/(7|8|9|10|11)-synyp\/?$/)?.[1]||0):0;
  const rank=(item)=>item.path==="/mektep"?0:gradeOf(item)?gradeOf(item)-6:item.path==="/sabaktastyk-kopiri"?6:item.path==="/universitet"?7:item.path==="/korytyndy-diagnostika"?8:9;
  return items.filter(item=>!item.parent_id||gradeOf(item)).sort((a,b)=>rank(a)-rank(b)||(a.sort_order||0)-(b.sort_order||0)||a.title.localeCompare(b.title,"kk"));
}
